import React from "react";
import { useState, useEffect } from "react";
import axios from "axios";
import { Link } from "react-router-dom";

const Summary = () => {
  const [ holdingsCount , setHoldingsCount ] = useState(0);
  const [ marginAvailable, setMarginAvailable] = useState(0);
  const [user , setUser] = useState(null);
  const [holdings, setHoldings] = useState([]);
  const [portfolio, setPortfolio] = useState({
    currentValue: 0,
    investment: 0,
    pnl: 0,
    pnlPercent: 0,
  });
  const [marginsUsed, setMarginsUsed] = useState(0);
  const [loading, setLoading] = useState(false);
  const [lastUpdated, setLastUpdated] = useState(null);


  useEffect(()=>{
    axios.get("http://localhost:3002/me", { withCredentials: true }).then((res)=>{
      setUser(res.data.user);
    }).catch((err)=>{
      console.log("Error fetching user:", err)
    })
  }, [])


  // Fetch live portfolio data with real-time prices
  const fetchLivePortfolioData = async () => {
    try {
      setLoading(true);
      const res = await axios.get("http://localhost:3002/api/livePortfolio", { withCredentials: true });
      
      if (res.data && res.data.portfolio) {
        setHoldingsCount(res.data.portfolio.length);
        setHoldings(res.data.portfolio);
        setPortfolio(res.data.summary);
        setLastUpdated(new Date().toLocaleTimeString());
      }
      setLoading(false);
    } catch (err) {
      console.log("Error fetching live portfolio:", err);
      setLoading(false);
    }
  };

  // Initial load
  useEffect(() => {
    fetchLivePortfolioData();
  }, []);

  // Auto-refresh prices every 5 seconds
  useEffect(() => {
    const interval = setInterval(() => {
      fetchLivePortfolioData();
    }, 5000); // Update every 5 seconds

    return () => clearInterval(interval);
  }, []);

  useEffect(()=>{
    axios.get("http://localhost:3002/funds", { withCredentials: true }).then((res)=>{
      setMarginAvailable(res.data.availableFunds);
    }).catch((err)=>{
      console.log("Error fetching funds:", err);
    })
  }, [])
  return (
    <>
      <div className="username">
        <h6>{user?.fullName || "User"}</h6>
        <div style={{ fontSize: "12px", color: "#999", marginTop: "5px" }}>
          {loading ? "Updating..." : lastUpdated && `Last updated: ${lastUpdated}`}
        </div>
        <hr className="divider" />
      </div>

      <div className="section">
        <span>
          <p>Equity</p>
        </span>

        <div className="data">
          <div className="first">
            <h3>₹{marginAvailable.toLocaleString('en-IN', { maximumFractionDigits: 2 })}</h3>
            <p>Margin Available</p>
          </div>
          <hr />

          <div className="second">
            <p>
              Margins used <span>₹{marginsUsed.toLocaleString('en-IN', { maximumFractionDigits: 2 })}</span>{" "}
            </p>
            <p>
              Opening balance <span>₹{(marginAvailable + marginsUsed).toLocaleString('en-IN', { maximumFractionDigits: 2 })}</span>{" "}
            </p>
          </div>
        </div>
        <hr className="divider" />
      </div>

      <div className="section">
        <span>
          <p>Holdings({holdingsCount})</p>
          <button 
            onClick={fetchLivePortfolioData}
            style={{
              background: "none",
              border: "none",
              color: "#2c2c2c",
              cursor: "pointer",
              fontSize: "12px",
              padding: "5px 10px"
            }}
            title="Refresh live prices"
          >
            🔄 Refresh
          </button>
        </span>

        <div className="data">
          <div className="first">
            <h3 className={portfolio.pnl >= 0 ? "profit" : "loss"}>
              ₹{Math.abs(portfolio.pnl).toLocaleString('en-IN', { maximumFractionDigits: 2 })} <small>{portfolio.pnl >= 0 ? '+' : ''}{portfolio.pnlPercent}%</small>{" "}
            </h3>
            <p>P&L</p>
          </div>
          <hr />

          <div className="second">
            <p>
              Current Value <span>₹{portfolio.currentValue.toLocaleString('en-IN', { maximumFractionDigits: 2 })}</span>{" "}
            </p>
            <p>
              Investment <span>₹{portfolio.investment.toLocaleString('en-IN', { maximumFractionDigits: 2 })}</span>{" "}
            </p>
          </div>
        </div>
        <hr className="divider" />
      </div>
    </>
  );
};

export default Summary;
